//! The AMS classes' top matter (amsart.cls 457-662) against pdfLaTeX.
//!
//! `tests/oracle/amsart/expected.json` is generated by `generate.py` there
//! (oracle only; Cargo never runs TeX): for each probe under `probes/`, the
//! whole page text pdfTeX set with all whitespace removed. The compiler must
//! set every piece of top matter the class sets -- the uppercased title
//! (`\@settitle`), the uppercased "A AND B" author line (`\@setauthors`),
//! the dedication, the unmarked `\@adminfootnotes` (date, subject
//! classification, key words, every `\thanks`), and `\@setaddresses` at
//! `\end{document}` -- and report no error. Each expected piece is checked
//! against the oracle text too, so a probe change that drops one fails here
//! rather than silently passing.

use std::path::Path;

use flashtex_compiler::diagnostics::Severity;
use flashtex_compiler::incremental::{compile_full, LayoutConstraints};
use flashtex_compiler::json::{self, Value};

/// The compiler's whole page text, whitespace removed, and its errors.
fn squashed_text(source: &str) -> (String, Vec<String>) {
    let result = compile_full(source, LayoutConstraints::default());
    let errors: Vec<String> = result
        .diagnostics
        .iter()
        .filter(|d| d.severity == Severity::Error)
        .map(|d| d.message.clone())
        .collect();
    let text: String = result
        .pages
        .iter()
        .flat_map(|page| page.items.iter().map(|item| item.text.as_str()))
        .flat_map(|t| t.chars().filter(|c| !c.is_whitespace()))
        .collect();
    (text, errors)
}

const PIECES: &[&str] = &[
    "ASTUDYOFTHINGS",
    "ALICEONEANDBOBTWO",
    "Dedicatedtosomeone",
    "Bodytextofthearticle.",
    "DepartmentofMathematics,SomeUniversity,City",
    "Emailaddress:alice@example.org",
    "InstituteofThings,Elsewhere",
    "Currentaddress:Somewhereelse",
    "URL:http://example.org/bob",
    "Date:January1,2025.",
    "2020MathematicsSubjectClassification.Primary05C15;Secondary05C10.",
    "Keywordsandphrases.Graphs,colourings.",
    "Supportedbygrantone.",
    "Thesecondauthorwassupportedbygranttwo.",
];

#[test]
fn amsart_top_matter_matches_pdflatex_text() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/oracle/amsart");
    let root = json::parse(&std::fs::read_to_string(dir.join("expected.json")).unwrap()).unwrap();
    let Some(Value::Obj(probes)) = root.get("probes") else { panic!("probes") };
    let probe = probes.get("topmatter.tex").expect("topmatter.tex");
    let oracle = probe.get("text").and_then(Value::as_str).expect("text");
    let source = std::fs::read_to_string(dir.join("probes/topmatter.tex")).unwrap();
    let (text, errors) = squashed_text(&source);
    assert!(errors.is_empty(), "{errors:?}");
    for piece in PIECES {
        assert!(oracle.contains(piece), "oracle lacks {piece}: {oracle}");
        assert!(text.contains(piece), "compiler lacks {piece}: {text}");
    }
    // No `\date{\today}` default and no numbered `\thanks` marks: the AMS
    // classes set neither.
    assert!(!text.contains("2026"), "{text}");
}

#[test]
fn thanks_inside_author_is_the_class_error() {
    let (text, errors) = squashed_text(
        "\\documentclass{amsart}\\title{T}\\author{A\\thanks{Grant.}}\\begin{document}\\maketitle x\\end{document}",
    );
    assert!(errors.iter().any(|e| e.contains("not inside author name")), "{errors:?}");
    assert!(!text.contains("Grant"), "{text}");
}

#[test]
fn three_authors_are_joined_with_commas_and_and() {
    let (text, errors) = squashed_text(
        "\\documentclass{amsart}\\title{T}\\author{A One}\\author{B Two}\\author{C Three}\\begin{document}\\maketitle x\\end{document}",
    );
    assert!(errors.is_empty(), "{errors:?}");
    assert!(text.contains("AONE,BTWO,ANDCTHREE"), "{text}");
}

#[test]
fn unknown_subjclass_edition_warns_and_sets_2020() {
    let result = compile_full(
        "\\documentclass{amsart}\\title{T}\\subjclass[1999]{05C15}\\begin{document}\\maketitle x\\end{document}",
        LayoutConstraints::default(),
    );
    assert!(result.diagnostics.iter().any(|d| d.message.contains("Unknown edition (1999)")));
    let text: String = result.pages.iter().flat_map(|p| p.items.iter().map(|i| i.text.clone())).collect();
    assert!(text.contains("2020 Mathematics Subject Classification."), "{text}");
}

#[test]
fn article_class_is_unchanged_by_the_ams_commands() {
    // Under article `\keywords` stays unknown and `\thanks` outside the title
    // block keeps its own diagnostic.
    let result = compile_full(
        "\\documentclass{article}\\title{T}\\begin{document}\\maketitle\\thanks{x}\\end{document}",
        LayoutConstraints::default(),
    );
    assert!(result.diagnostics.iter().any(|d| d.message.contains("\\thanks outside")));
}
